]

[
  "No optimizer, shared-link discovery or inferred end-to-end traffic coverage"
]

[
  "Independent declared traffic budgets; latency and service implementation are unknown"
]

[
  "Conditional scenario envelope, not a dated forecast or probability distribution"
]

[
  "MLA needs explicit latent-cache and reconstruction traffic inputs; GQA formula must not be reused"
]

[
  "Positioning only; excluded from sizing, ranking and internal input requests"
